use std::collections::BTreeSet;

wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Mark every considered id as seen. BTreeSet dedupes so that a repeated
        // id is written once and counted once.
        let ids: BTreeSet<&str> = published.considered.iter().map(|s| s.as_str()).collect();

        let mut recorded: u32 = 0;
        for id in ids {
            crate::aap::caps::state_rw::put(id, &published.date);
            recorded = recorded.saturating_add(1);
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
